export type DotState = "idle" | "thinking" | "working" | "success" | "error" | "lost"
export type DotSize = "sm" | "md" | "lg"

export interface SizePreset {
  /** Box edge in CSS px. */
  px: number
  /** Half-extent of the model as a share of the box; perspective grows near parts, so this leaves room. */
  fit: number
  /** Dots drawn at density 1. */
  dots: number
  /** Dot radius in CSS px before depth and perspective. */
  radius: number
  spin: boolean
  /** How strongly glowing dots brighten and swell. */
  glow: number
  fps: number
  /** Brightness levels: one canvas fill per level. */
  levels: number
  /** Uniform dot size instead of perspective-scaled. */
  flat: boolean
}

export const SIZES: Record<DotSize, SizePreset> = {
  sm: { px: 64, fit: 0.38, dots: 520, radius: 0.5, spin: false, glow: 0.3, fps: 30, levels: 4, flat: true },
  md: { px: 120, fit: 0.34, dots: 2800, radius: 0.42, spin: true, glow: 1, fps: 60, levels: 8, flat: false },
  lg: { px: 340, fit: 0.34, dots: 7000, radius: 0.5, spin: true, glow: 1, fps: 60, levels: 8, flat: false },
}

/** Seconds a one-shot state takes to settle. */
export const TERMINAL: Partial<Record<DotState, number>> = { success: 2.2, error: 2.6 }

export const YAW0 = 0.5
export const TILT = 0.18
export const CAM = 3.4

const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v)
const easeOut = (t: number) => 1 - Math.pow(1 - t, 3)
const easeBack = (t: number) => {
  const c = 1.6
  return 1 + (c + 1) * Math.pow(t - 1, 3) + c * Math.pow(t - 1, 2)
}
const bump = (x: number) => (x <= 0 || x >= 1 ? 0 : Math.pow(Math.sin(Math.PI * x), 2))
const frac = (v: number) => v - Math.floor(v)

/** Deterministic pseudo-random 0..1 for dot `i` and channel `k`. */
export function hash(i: number, k: number): number {
  const x = Math.sin((i * 3 + k + 1) * 78.233) * 12345.678
  return x - Math.floor(x)
}

export function clampProgress(p: number | undefined): number | undefined {
  return p === undefined || Number.isNaN(p) ? undefined : clamp01(p)
}

/** Where the whole object faces. `look` (-1..1) is where the cursor is, smoothed. */
export function yawFor(state: DotState, preset: SizePreset, t: number, st: number, look: number): number {
  if (!preset.spin) return YAW0 + 0.22 * Math.sin(t * 0.7)
  switch (state) {
    case "thinking":
      return YAW0 + t * 0.3
    case "working":
      return YAW0 + t * 0.55
    case "success":
      return YAW0 + (1 - easeOut(clamp01(st / 1.6))) * 2.4 + look * 0.35
    case "lost":
      return YAW0 + 0.85 * Math.sin(t * 0.45) + look * 0.2
    case "idle":
      return YAW0 + 0.18 * Math.sin(t * 0.4) + look * 0.45
    default:
      return YAW0
  }
}

/**
 * One dot at time `t` (seconds since mount) and `st` (seconds since the state began).
 * Writes `[x, y, z, glow, alpha]` into `out`.
 */
export function dotAt(
  positions: Float32Array,
  flow: Float32Array,
  i: number,
  state: DotState,
  t: number,
  st: number,
  progress: number | undefined,
  out: Float32Array,
): void {
  let x = positions[i * 3]
  let y = positions[i * 3 + 1]
  let z = positions[i * 3 + 2]
  let glow = 0
  let alpha = 1
  const s = flow[i]
  const seed = hash(i, 7)
  const breathe = (a: number, speed: number) => {
    const b = 1 + a * Math.sin(t * speed)
    x *= b
    y *= b
    z *= b
  }

  if (state === "idle") {
    breathe(0.018, 1.1)
  } else if (state === "thinking") {
    breathe(0.025, 1.7)
    // Every 7s a head-to-tail band of dots loosens into a swirling cloud and snaps back, like computing.
    const w = (t % 7) / 7
    const amt = Math.pow(bump((w - 0.1 - s * 0.35) / 0.35), 0.8) * (seed < 0.6 ? 1 : 0.25)
    if (amt > 0) {
      const a = amt * (1.2 + seed * 1.5)
      const c = Math.cos(a)
      const sn = Math.sin(a)
      const e = 1 + amt * (0.18 + 0.25 * seed)
      const nx = (x * c + z * sn) * e
      const nz = (-x * sn + z * c) * e
      x = nx
      z = nz
      y = y * e + amt * 0.1 * Math.sin(seed * 30)
      glow = amt * 0.45
    }
  } else if (state === "working") {
    const phase = ((t * 0.55) % 1.2) - 0.1 // glow travels head to tail
    const d = (s - phase) / 0.09
    glow = Math.exp(-d * d)
    const push = 1 + 0.06 * glow
    x *= push
    y *= push
    z *= push
    if (seed < 0.1) {
      // Embers: a few dots drift up and fade.
      const f = frac(t * 0.25 + seed * 20)
      y += f * 0.55
      x += (seed - 0.05) * f
      alpha *= 1 - f
    }
  } else if (state === "lost") {
    breathe(0.012, 0.9)
    if (seed < 0.35) {
      // A third of the dots wander off, each on its own path.
      const f = frac(t * (0.09 + seed * 0.25) + seed * 30)
      const a = seed * 90
      const up = hash(i, 4) * 2 - 1
      x += Math.cos(a) * f * 1.7
      y += up * f * 1.1
      z += Math.sin(a) * f * 1.7
      alpha *= Math.pow(1 - f, 0.7)
    }
  } else if (state === "success") {
    const delay = s * 0.55 + seed * 0.35
    const k = easeBack(clamp01((st - delay) / 0.9))
    const u = hash(i, 0) * 2 - 1
    const a = hash(i, 1) * Math.PI * 2
    const r = 1.2 + 0.6 * hash(i, 2)
    const q = Math.sqrt(1 - u * u)
    const sx = q * Math.cos(a) * r
    const sy = u * r
    const sz = q * Math.sin(a) * r
    x = sx + (x - sx) * k
    y = sy + (y - sy) * k
    z = sz + (z - sz) * k
    alpha = 0.25 + 0.75 * clamp01(k)
    glow = Math.max(0, 1 - Math.abs(st - delay - 0.9) * 4) * 0.8
  } else if (state === "error") {
    // Evaporate: most dots rise, drift apart and fade; a thin layer of ash settles at the base.
    const delay = seed * 0.5 + (1 - s) * 0.3
    const f = clamp01((st - delay) / 1.6)
    if (seed > 0.85) {
      y = Math.max(-1, y - f * f * 2.2)
      alpha = 1 - 0.65 * f
    } else {
      const drift = Math.sin(seed * 60 + t * 2) * 0.12
      y += f * f * 0.9
      x += (seed - 0.45) * f * 0.7 + drift * f
      z += (hash(i, 3) - 0.5) * f * 0.7
      alpha = 1 - f
    }
  }

  // Determinate progress: dots are revealed head to tail; the rest stay as a faint ghost of the shape.
  if (progress !== undefined && (state === "working" || state === "thinking")) {
    const shown = clamp01((progress * 1.08 - s) / 0.08)
    alpha *= 0.07 + 0.93 * shown
    glow += (1 - Math.abs(shown * 2 - 1)) * 0.5 * (shown > 0 && shown < 1 ? 1 : 0)
  }

  out[0] = x
  out[1] = y
  out[2] = z
  out[3] = glow
  out[4] = alpha
}

import { hash } from "@/components/ui/dot-object-engine"

/**
 * What you pass to `DotObject`: plain data (dot count and the dots as base64), so a Server Component can hand
 * it to the client. Typed arrays can't make that trip: React transfers their buffers and leaves them detached.
 */
export interface DotModel {
  n: number
  /** See `encodeModel`. */
  data: string
}

/** A decoded model: positions (x, y, z per dot, within -1..1) and a head-to-tail flow value (0..1) per dot. */
export interface DotCloud {
  n: number
  positions: Float32Array
  flow: Float32Array
}

/** Compact form: base64 of Int16 x, y, z (scaled by 32767) per dot, then Uint8 flow (scaled by 255) per dot. */
export function encodeModel(m: DotCloud): string {
  const bytes = new Uint8Array(m.n * 7)
  const view = new DataView(bytes.buffer)
  for (let i = 0; i < m.n * 3; i++) view.setInt16(i * 2, Math.round(Math.max(-1, Math.min(1, m.positions[i])) * 32767), true)
  for (let i = 0; i < m.n; i++) bytes[m.n * 6 + i] = Math.round(m.flow[i] * 255)
  let binary = ""
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000))
  return btoa(binary)
}

export function decodeModel(data: string): DotCloud {
  const binary = atob(data)
  const bytes = Uint8Array.from(binary, (c) => c.charCodeAt(0))
  const n = bytes.length / 7
  const view = new DataView(bytes.buffer)
  const positions = new Float32Array(n * 3)
  const flow = new Float32Array(n)
  for (let i = 0; i < n * 3; i++) positions[i] = view.getInt16(i * 2, true) / 32767
  for (let i = 0; i < n; i++) flow[i] = bytes[n * 6 + i] / 255
  return { n, positions, flow }
}

/**
 * Order the first `k` dots by farthest-point sampling (starting at index 0), then the rest as they were.
 * Any prefix of the first `k` is an evenly spread sample of the shape, so a small preset keeps the whole silhouette.
 */
export function spreadOrder(positions: Float32Array, k: number): Uint32Array {
  const n = positions.length / 3
  const order = new Uint32Array(n)
  const taken = new Uint8Array(n)
  const near = new Float32Array(n).fill(Infinity)
  const picks = Math.min(k, n)
  let count = 0
  if (n > 0) {
    order[count++] = 0
    taken[0] = 1
  }
  for (let cur = 0; count < picks; ) {
    let best = -1
    let bestDist = -1
    for (let i = 0; i < n; i++) {
      const dx = positions[i * 3] - positions[cur * 3]
      const dy = positions[i * 3 + 1] - positions[cur * 3 + 1]
      const dz = positions[i * 3 + 2] - positions[cur * 3 + 2]
      const d = dx * dx + dy * dy + dz * dz
      if (d < near[i]) near[i] = d
      if (!taken[i] && near[i] > bestDist) {
        bestDist = near[i]
        best = i
      }
    }
    taken[best] = 1
    order[count++] = best
    cur = best
  }
  for (let i = 0; i < n; i++) if (!taken[i]) order[count++] = i
  return order
}

export function reorder(m: DotCloud, order: Uint32Array): DotCloud {
  const positions = new Float32Array(m.n * 3)
  const flow = new Float32Array(m.n)
  order.forEach((from, to) => {
    positions.set(m.positions.subarray(from * 3, from * 3 + 3), to * 3)
    flow[to] = m.flow[from]
  })
  return { n: m.n, positions, flow }
}

const decoded = new Map<string, DotCloud>()

/** The dots of a model, decoded once and shared. Call it on the client, where the dots are drawn. */
export function cloudOf(model: DotModel): DotCloud {
  let cloud = decoded.get(model.data)
  if (!cloud) decoded.set(model.data, (cloud = decodeModel(model.data)))
  return cloud
}

const SPREAD = 600
const cache = new Map<string, DotModel>()

/** Shuffle deterministically, flow top pole to bottom pole, then spread the first dots so any prefix is even. */
function fromPoints(points: [number, number, number][]): DotModel {
  const shuffle = points.map((_, i) => i)
  for (let i = shuffle.length - 1; i > 0; i--) {
    const j = Math.floor(hash(i, 5) * (i + 1))
    ;[shuffle[i], shuffle[j]] = [shuffle[j], shuffle[i]]
  }
  const positions = new Float32Array(points.length * 3)
  const flow = new Float32Array(points.length)
  shuffle.forEach((from, to) => {
    positions.set(points[from], to * 3)
    flow[to] = (1 - points[from][1]) / 2
  })
  const cloud = reorder({ n: points.length, positions, flow }, spreadOrder(positions, SPREAD))
  const data = encodeModel(cloud)
  const model = { n: cloud.n, data }
  decoded.set(data, cloud)
  return model
}

function memo(key: string, make: () => DotModel): DotModel {
  let m = cache.get(key)
  if (!m) cache.set(key, (m = make()))
  return m
}

/** An even spiral of dots over a unit sphere. */
export function sphereDots(count = 4200): DotModel {
  return memo(`dots:${count}`, () => {
    const golden = Math.PI * (3 - Math.sqrt(5))
    const points = Array.from({ length: count }, (_, i): [number, number, number] => {
      const y = 1 - (2 * (i + 0.5)) / count
      const r = Math.sqrt(1 - y * y)
      return [Math.cos(i * golden) * r, y, Math.sin(i * golden) * r]
    })
    return fromPoints(points)
  })
}

/** Dots packed along latitude rings and meridians: reads as a wireframe globe. */
export function sphereLines(rings = 11, meridians = 14, perLine = 150): DotModel {
  return memo(`lines:${rings}:${meridians}:${perLine}`, () => {
    const points: [number, number, number][] = []
    for (let k = 1; k < rings; k++) {
      const lat = Math.PI * (k / rings)
      const y = Math.cos(lat)
      const r = Math.sin(lat)
      const m = Math.round(perLine * r)
      for (let i = 0; i < m; i++) {
        const a = (i / m) * Math.PI * 2
        points.push([Math.cos(a) * r, y, Math.sin(a) * r])
      }
    }
    for (let j = 0; j < meridians; j++) {
      const a = (j / meridians) * Math.PI * 2
      for (let i = 0; i <= perLine / 2; i++) {
        const lat = Math.PI * (i / (perLine / 2))
        points.push([Math.cos(a) * Math.sin(lat), Math.cos(lat), Math.sin(a) * Math.sin(lat)])
      }
    }
    return fromPoints(points)
  })
}

import { CAM, TILT, dotAt, yawFor, type DotState, type SizePreset } from "@/components/ui/dot-object-engine"
import type { DotCloud } from "@/components/ui/dot-object-models"

/** How far, and how hard, a dot leans toward the cursor. */
const LEAN = 0.55
/** How quickly a dot's lean eases toward its target each frame. */
const EASE = 0.14

/** Cursor gravity: inside `reach` a dot leans toward the cursor, harder the closer it is. */
export function pull(px: number, py: number, cx: number, cy: number, reach: number): [number, number] {
  const dx = cx - px
  const dy = cy - py
  const d = Math.hypot(dx, dy)
  if (d >= reach) return [0, 0]
  const w = Math.pow(1 - d / reach, 2) * LEAN
  return [dx * w, dy * w]
}

export interface Painting {
  model: DotCloud
  preset: SizePreset
  state: DotState
  /** Seconds since mount. */
  t: number
  /** Seconds since the state began. */
  st: number
  progress?: number
  /** Where the cursor is, -1..1, smoothed. */
  look: number
  /** Cursor in canvas px, or null when gravity is off or the cursor is away. Offsets still ease back. */
  cursor: { x: number; y: number } | null
  /** Per-dot lean in px, owned by the caller and kept between frames. */
  offsets: { x: Float32Array; y: Float32Array }
  color: string
  /** Share of the preset's dots to draw. */
  density?: number
}

const clamp01 = (v: number) => (v < 0 ? 0 : v > 1 ? 1 : v)

/** Draw one frame at the preset's logical size; returns the number of dots drawn. */
export function paintDots(ctx: Pick<CanvasRenderingContext2D, "clearRect" | "fill" | "fillStyle" | "globalAlpha">, p: Painting): number {
  const { preset, model, offsets } = p
  const size = preset.px
  const count = Math.min(model.n, Math.round(preset.dots * (p.density ?? 1)), offsets.x.length)
  const yaw = yawFor(p.state, preset, p.t, p.st, p.look)
  const cy = Math.cos(yaw)
  const sy = Math.sin(yaw)
  const ct = Math.cos(TILT)
  const stt = Math.sin(TILT)
  const half = size / 2
  const scale = size * preset.fit
  const reach = size * 0.3
  const levels = preset.levels
  const paths = Array.from({ length: levels }, () => new Path2D())
  const used = new Uint8Array(levels)
  const out = new Float32Array(5)

  for (let i = 0; i < count; i++) {
    dotAt(model.positions, model.flow, i, p.state, p.t, p.st, p.progress, out)
    const x1 = out[0] * cy + out[2] * sy
    const z1 = -out[0] * sy + out[2] * cy
    const y2 = out[1] * ct - z1 * stt
    const z2 = out[1] * stt + z1 * ct
    const persp = CAM / (CAM - z2)
    let px = half + x1 * scale * persp
    let py = half - y2 * scale * persp
    // Every dot eases toward its own target lean, so dots spring back when the cursor leaves.
    const [lx, ly] = p.cursor ? pull(px, py, p.cursor.x, p.cursor.y, reach) : [0, 0]
    offsets.x[i] += (lx - offsets.x[i]) * EASE
    offsets.y[i] += (ly - offsets.y[i]) * EASE
    px += offsets.x[i]
    py += offsets.y[i]

    const depth = clamp01((z2 + 1) / 2)
    const shade = clamp01((0.15 + 0.85 * depth) * out[4] + out[3] * 0.6 * preset.glow)
    const level = Math.min(levels - 1, Math.floor(shade * levels))
    const r = preset.radius * (preset.flat ? 0.85 + 0.3 * depth : (0.65 + 0.7 * depth) * persp) * (1 + out[3] * 0.9 * preset.glow)
    paths[level].rect(px - r, py - r, r * 2, r * 2)
    used[level] = 1
  }

  ctx.clearRect(0, 0, size, size)
  ctx.fillStyle = p.color
  for (let level = 0; level < levels; level++) {
    if (!used[level]) continue
    ctx.globalAlpha = 0.18 + 0.72 * (level / (levels - 1))
    ctx.fill(paths[level])
  }
  ctx.globalAlpha = 1
  return count
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { SIZES, TERMINAL, clampProgress, type DotSize, type DotState } from "@/components/ui/dot-object-engine"
import { cloudOf, type DotModel } from "@/components/ui/dot-object-models"
import { paintDots } from "@/components/ui/dot-object-painter"

interface ShimmerTextProps extends React.ComponentProps<"span"> {
  /** Sweep a highlight across the text. Static when false, and under reduced motion. */
  busy?: boolean
}

function ShimmerText({ busy = false, className, ...props }: ShimmerTextProps) {
  return (
    <span
      data-slot="shimmer-text"
      data-busy={busy || undefined}
      className={cn(
        "text-sm font-medium whitespace-nowrap text-muted-foreground",
        busy &&
          "bg-[linear-gradient(100deg,var(--muted-foreground)_35%,var(--foreground)_50%,var(--muted-foreground)_65%)] bg-[length:250%_100%] bg-[position:100%_0] bg-clip-text text-transparent [animation:dot-shimmer_1.9s_linear_infinite] motion-reduce:bg-none motion-reduce:text-foreground motion-reduce:[animation:none]",
        className,
      )}
      {...props}
    />
  )
}

interface DotObjectProps extends Omit<React.ComponentProps<"div">, "children"> {
  model: DotModel
  /** What the object is doing, in words. Announced when `state` changes; shown when `showLabel` is set. */
  label: string
  state?: DotState
  size?: DotSize
  /** 0 to 1: reveals the shape head to tail while `working` or `thinking`. Omit when the length is unknown. */
  progress?: number
  /** Dots near the mouse lean toward it. Mouse only: off for touch, reduced motion and forced colours. */
  gravity?: boolean
  /** Show `label` as shimmering text: below the object, or beside it at `sm`. */
  showLabel?: boolean
  paused?: boolean
  /** Share of the size's dots to draw (0.2 to 2). Lower is lighter. */
  density?: number
  /** Multiplies animation time. Use above 1 for faster catalog previews. Default: 1. */
  playbackRate?: number
  /** Called once when `success` or `error` has finished playing. */
  onSettled?: (state: "success" | "error") => void
}

/* ── shared loop: one requestAnimationFrame for every instance on the page ─────────────────────── */

type Tick = (now: number) => void

const cursor = { x: 0, y: 0, on: false }
const onPointerMove = (e: PointerEvent) => {
  cursor.x = e.clientX
  cursor.y = e.clientY
  cursor.on = e.pointerType === "mouse"
}
const onPointerOut = (e: PointerEvent) => {
  if (!e.relatedTarget) cursor.on = false
}

const ticks = new Set<Tick>()
let frame = 0

function loop(now: number) {
  frame = 0
  for (const tick of ticks) tick(now)
  if (ticks.size) frame = requestAnimationFrame(loop)
}

function subscribe(tick: Tick): () => void {
  if (!ticks.size) {
    window.addEventListener("pointermove", onPointerMove)
    document.addEventListener("pointerout", onPointerOut)
  }
  ticks.add(tick)
  if (!frame) frame = requestAnimationFrame(loop)
  return () => {
    ticks.delete(tick)
    if (ticks.size) return
    cancelAnimationFrame(frame)
    frame = 0
    window.removeEventListener("pointermove", onPointerMove)
    document.removeEventListener("pointerout", onPointerOut)
  }
}

/** Per-instance animation state, kept outside React: it changes every frame. */
interface Run {
  last: number
  /** Seconds since mount, and since the current state began (both stop while paused). */
  t: number
  st: number
  settled: boolean
  /** The next tick must redraw even if the picture is otherwise still. */
  dirty: boolean
  visible: boolean
  look: number
  /** Frames left to keep drawing after gravity stops, so dots can spring back. */
  hot: number
  lastDraw: number
  colorCheck: number
  color: string
  ctx: CanvasRenderingContext2D | null
  offsets: { x: Float32Array; y: Float32Array }
}

const newRun = (): Run => ({
  last: 0,
  t: 0,
  st: 0,
  settled: false,
  dirty: true,
  visible: true,
  look: 0,
  hot: 0,
  lastDraw: 0,
  colorCheck: -Infinity,
  color: "",
  ctx: null,
  offsets: { x: new Float32Array(0), y: new Float32Array(0) },
})

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v))

function DotObject({
  model,
  label,
  state = "idle",
  size = "md",
  progress,
  gravity = true,
  showLabel = false,
  paused = false,
  density,
  playbackRate = 1,
  onSettled,
  className,
  ...props
}: DotObjectProps) {
  const preset = SIZES[size]
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const [initialRun] = React.useState(newRun)
  const run = React.useRef(initialRun)

  // Announce only changes after mount: remember the state we last saw and compare while rendering.
  const [seen, setSeen] = React.useState(state)
  const [announcement, setAnnouncement] = React.useState("")
  if (seen !== state) {
    setSeen(state)
    setAnnouncement(label)
  }

  // The loop reads the latest props without re-subscribing.
  const latest = React.useRef({ model, state, size, progress, gravity, paused, density, playbackRate, onSettled })
  React.useEffect(() => {
    latest.current = { model, state, size, progress, gravity, paused, density, playbackRate, onSettled }
    run.current.dirty = true
  })

  // A new state starts from its beginning; a pending `onSettled` for the old one can no longer fire.
  React.useEffect(() => {
    run.current.st = 0
    run.current.settled = false
    run.current.dirty = true
  }, [run, state])

  // Size the canvas for the preset and the screen.
  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const dpr = Math.min(2, window.devicePixelRatio || 1)
    canvas.width = canvas.height = Math.round(preset.px * dpr)
    const ctx = canvas.getContext("2d")
    ctx?.setTransform(dpr, 0, 0, dpr, 0, 0)
    run.current.ctx = ctx
    run.current.dirty = true
  }, [run, preset.px])

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const r = run.current
    // matchMedia is missing in some test environments and old browsers: treat as "no preference".
    const media = (query: string) => window.matchMedia?.(query) ?? { matches: false }
    const reduce = media("(prefers-reduced-motion: reduce)")
    const coarse = media("(pointer: coarse)")
    const forced = media("(forced-colors: active)")
    const observer = typeof IntersectionObserver === "undefined" ? null : new IntersectionObserver(([e]) => (r.visible = e.isIntersecting))
    observer?.observe(canvas)

    const unsubscribe = subscribe((now) => {
      const p = latest.current
      const dt = r.last ? Math.min((now - r.last) / 1000, 0.1) : 0
      r.last = now
      if (!p.paused) {
        const step = dt * Math.max(0.1, p.playbackRate ?? 1)
        r.t += step
        r.st += step
      }
      const end = TERMINAL[p.state]
      const rm = reduce.matches
      // Reduced motion shows one still frame: the final one for a state that has an ending.
      const t = rm ? 0 : r.t
      const st = rm ? (end ?? 0) : end === undefined ? r.st : Math.min(r.st, end)

      if (end !== undefined && st >= end && !r.settled && !p.paused) {
        r.settled = true
        p.onSettled?.(p.state as "success" | "error")
      }

      // Dark mode and forced colours change the element's colour without a prop change.
      if (now - r.colorCheck > 500) {
        r.colorCheck = now
        const color = getComputedStyle(canvas).color
        if (color !== r.color) {
          r.color = color
          r.dirty = true
        }
      }

      const ctx = r.ctx
      // A paused instance still draws once per change, so it never sits blank.
      if (!ctx || !r.visible || (p.paused && !r.dirty)) return

      const settledFrame = rm || (end !== undefined && st >= end)
      const gravityOn = p.gravity && !rm && !coarse.matches && !forced.matches
      const cursorOn = gravityOn && cursor.on
      const box = cursorOn ? canvas.getBoundingClientRect() : null
      const cx = box ? cursor.x - box.left : 0
      const cy = box ? cursor.y - box.top : 0
      const lookTarget = box ? clamp((cx - SIZES[p.size].px / 2) / 400, -1, 1) : 0
      r.look += (lookTarget - r.look) * 0.06
      r.hot = gravityOn && (cursorOn || Math.abs(r.look) > 0.002) ? 90 : Math.max(0, r.hot - 1)

      if (settledFrame && !r.dirty && r.hot === 0) return
      const fps = SIZES[p.size].fps
      if (!r.dirty && now - r.lastDraw < 1000 / fps - 4) return
      r.lastDraw = now
      r.dirty = false

      const cloud = cloudOf(p.model)
      if (r.offsets.x.length < cloud.n) r.offsets = { x: new Float32Array(cloud.n), y: new Float32Array(cloud.n) }
      paintDots(ctx, {
        model: cloud,
        preset: SIZES[p.size],
        state: p.state,
        t,
        st,
        progress: clampProgress(p.progress),
        look: r.look,
        cursor: box ? { x: cx, y: cy } : null,
        offsets: r.offsets,
        color: r.color,
        density: p.density,
      })
    })
    return () => {
      unsubscribe()
      observer?.disconnect()
    }
  }, [run])

  const busy = state === "thinking" || state === "working"
  return (
    <div
      data-slot="dot-object"
      data-state={state}
      data-size={size}
      className={cn("inline-flex items-center gap-2.5 text-foreground", size === "sm" ? "flex-row gap-2" : "flex-col", className)}
      {...props}
    >
      <div className="relative flex-none" style={{ width: preset.px, height: preset.px }}>
        <canvas ref={canvasRef} aria-hidden="true" className="absolute inset-0 block" style={{ width: preset.px, height: preset.px }} />
      </div>
      {showLabel && (
        <ShimmerText busy={busy} aria-hidden="true">
          {label}
        </ShimmerText>
      )}
      <div role="status" className="sr-only">
        {announcement}
      </div>
    </div>
  )
}

export { DotObject, ShimmerText }
export type { DotObjectProps, ShimmerTextProps }
